export function getBySemanticField(field: string): VocabWord[] {
  return A1_VOCABULARY.filter(word => word.semanticField === field);
}

export function getWordById(id: string): VocabWord | undefined {
  return A1_VOCABULARY.find(word => word.id === id);
}

export function searchWords(query: string): VocabWord[] {
  const lowerQuery = query.toLowerCase();
  return A1_VOCABULARY.filter(word => 
    word.german.toLowerCase().includes(lowerQuery) ||
    word.english.toLowerCase().includes(lowerQuery) ||
    word.arabic.includes(lowerQuery)
  );
}
